// Agni Royale — tiny runtime UI kit (uGUI built from code; all art is our own, generated by Tools/ui_gen/*.py).
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

namespace Agni.UI
{
    public static class Pal
    {
        public static readonly Color Saffron = Hex("#FF9C2C");
        public static readonly Color SaffronDeep = Hex("#F0531C");
        public static readonly Color Gold = Hex("#FFC83D");
        public static readonly Color Cream = Hex("#FFF3DC");
        public static readonly Color CreamDim = Hex("#E9D6B8");
        public static readonly Color Teal = Hex("#0E3B44");
        public static readonly Color TealDeep = Hex("#08262D");
        public static readonly Color TealLight = Hex("#1F6B70");
        public static readonly Color Ink = Hex("#2A140C");
        public static readonly Color Red = Hex("#FF5A5A");
        public static Color Hex(string h) { ColorUtility.TryParseHtmlString(h, out var c); return c; }
        public static Color A(Color c, float a) { c.a = a; return c; }
    }

    public static class K
    {
        static Font _title, _body;
        public static Font Title { get { if (_title == null) _title = Resources.Load<Font>("AgniIntro/LilitaOne-Regular") ?? Builtin(); return _title; } }
        public static Font Body { get { if (_body == null) _body = Resources.Load<Font>("AgniIntro/Baloo2") ?? Builtin(); return _body; } }
        static Font Builtin() => Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

        static readonly Dictionary<string, Sprite> cache = new Dictionary<string, Sprite>();
        public static Sprite S(string name)
        {
            if (string.IsNullOrEmpty(name)) return null;
            if (cache.TryGetValue(name, out var s) && s != null) return s;
            s = Resources.Load<Sprite>("AgniUI/" + name);
            if (s == null) Debug.LogWarning("[AgniUI] missing sprite " + name);
            cache[name] = s; return s;
        }

        public static RectTransform R(string name, Transform parent)
        {
            var go = new GameObject(name, typeof(RectTransform));
            go.layer = parent != null ? parent.gameObject.layer : 5;
            var rt = (RectTransform)go.transform; rt.SetParent(parent, false); return rt;
        }
        /// anchor = point inside parent (0..1), pivot same as anchor unless given; pos in px from that anchor.
        public static RectTransform Place(this RectTransform rt, Vector2 anchor, Vector2 pos, Vector2 size, Vector2? pivot = null)
        {
            rt.anchorMin = rt.anchorMax = anchor; rt.pivot = pivot ?? anchor; rt.anchoredPosition = pos; rt.sizeDelta = size; return rt;
        }
        public static RectTransform Fill(this RectTransform rt, float l = 0, float b = 0, float r = 0, float t = 0)
        {
            rt.anchorMin = Vector2.zero; rt.anchorMax = Vector2.one; rt.pivot = new Vector2(0.5f, 0.5f);
            rt.offsetMin = new Vector2(l, b); rt.offsetMax = new Vector2(-r, -t); return rt;
        }

        public static Image Img(Transform parent, string name, string sprite, Color color, float ppuMul = 1f)
        {
            var rt = R(name, parent); var im = rt.gameObject.AddComponent<Image>();
            im.sprite = S(sprite); im.color = color; im.raycastTarget = false;
            if (im.sprite != null && im.sprite.border.sqrMagnitude > 0) { im.type = Image.Type.Sliced; im.pixelsPerUnitMultiplier = ppuMul; }
            return im;
        }

        public static Text Txt(Transform parent, string name, string text, int size, Color color, TextAnchor anchor = TextAnchor.MiddleCenter, bool title = false)
        {
            var rt = R(name, parent); var t = rt.gameObject.AddComponent<Text>();
            t.font = title ? Title : Body; t.fontSize = size; t.color = color; t.alignment = anchor; t.text = text;
            t.horizontalOverflow = HorizontalWrapMode.Overflow; t.verticalOverflow = VerticalWrapMode.Overflow;
            t.raycastTarget = false; t.supportRichText = true; return t;
        }
        public static T Outline<T>(this T g, Color c, float d = 3f) where T : Graphic
        {
            var o = g.gameObject.AddComponent<Outline>(); o.effectColor = c; o.effectDistance = new Vector2(d, -d); return g;
        }
        public static T Shadow<T>(this T g, Color c, float x = 0, float y = -5) where T : Graphic
        {
            var o = g.gameObject.AddComponent<Shadow>(); o.effectColor = c; o.effectDistance = new Vector2(x, y); return g;
        }

        /// Big bevelled game button: shadow + tinted bevel body + label. Returns the Button.
        public static Button Btn(Transform parent, string name, string label, Color body, int fontSize, System.Action onClick, string sprite = "btn_24", Color? labelColor = null)
        {
            if (body == Pal.Saffron && sprite.StartsWith("btn_")) { sprite = "btno_" + sprite.Substring(4); body = Color.white; }
            var rt = R(name, parent);
            var sh = Img(rt, "Shadow", "rr_24", Pal.A(Color.black, 0.35f)); sh.rectTransform.Fill(0, -8, 0, 8);
            var im = rt.gameObject.AddComponent<Image>(); im.sprite = S(sprite); im.type = Image.Type.Sliced; im.color = body;
            var b = rt.gameObject.AddComponent<Button>(); b.targetGraphic = im;
            var cb = b.colors; cb.highlightedColor = new Color(1.05f, 1.05f, 1.05f); cb.pressedColor = new Color(0.82f, 0.82f, 0.82f); cb.fadeDuration = 0.06f; b.colors = cb;
            if (onClick != null) b.onClick.AddListener(() => onClick());
            if (!string.IsNullOrEmpty(label))
            {
                var t = Txt(rt, "Label", label, fontSize, labelColor ?? Color.white, TextAnchor.MiddleCenter, true);
                t.rectTransform.Fill(); t.Shadow(Pal.A(Pal.Ink, 0.55f), 0, -4);
            }
            rt.gameObject.AddComponent<PressBounce>();
            return b;
        }

        public static Image Icon(Transform parent, string sprite, Vector2 size, Color c)
        {
            var im = Img(parent, "Icon_" + sprite, sprite, c); im.preserveAspect = true; im.rectTransform.sizeDelta = size; return im;
        }

        /// Full-screen dim + centred card. Returns the card RectTransform; root = card.parent.
        public static RectTransform Modal(Transform canvas, string name, Vector2 size, out GameObject root)
        {
            var r = R(name, canvas); r.Fill(); root = r.gameObject;
            var dim = r.gameObject.AddComponent<Image>(); dim.color = new Color(0.02f, 0.06f, 0.07f, 0.72f); dim.raycastTarget = true;
            var card = R("Card", r).Place(new Vector2(0.5f, 0.5f), Vector2.zero, size);
            var sh = Img(card, "Shadow", "shadow_24", Pal.A(Color.black, 0.6f)); sh.rectTransform.Fill(-50, -60, -50, -40);
            var bg = Img(card, "Bg", "rr_40", Pal.Hex("#FFF6E6")); bg.rectTransform.Fill();
            var band = Img(card, "Band", "rr_40", Pal.Hex("#FFE2B8")); band.rectTransform.Fill(0, 0, 0, 0); band.rectTransform.anchorMin = new Vector2(0, 1); band.rectTransform.offsetMin = new Vector2(0, -150);
            var bandFix = Img(card, "BandFix", null, Pal.Hex("#FFE2B8")); bandFix.rectTransform.anchorMin = new Vector2(0, 1); bandFix.rectTransform.anchorMax = new Vector2(1, 1); bandFix.rectTransform.pivot = new Vector2(0.5f, 1); bandFix.rectTransform.anchoredPosition = new Vector2(0, -100); bandFix.rectTransform.sizeDelta = new Vector2(0, 50);
            var line = Img(card, "BandLine", null, Pal.Saffron); line.rectTransform.anchorMin = new Vector2(0, 1); line.rectTransform.anchorMax = new Vector2(1, 1); line.rectTransform.pivot = new Vector2(0.5f, 1); line.rectTransform.anchoredPosition = new Vector2(0, -150); line.rectTransform.sizeDelta = new Vector2(0, 6);
            return card;
        }

        public static Button CloseX(Transform card, System.Action onClick)
        {
            var b = Btn(card, "Close", null, Pal.SaffronDeep, 10, onClick, "btn_40");
            ((RectTransform)b.transform).Place(new Vector2(1, 1), new Vector2(-28, -28), new Vector2(96, 96), new Vector2(1, 1));
            var ic = Icon(b.transform, "ic_close", new Vector2(46, 46), Color.white);
            return b;
        }
    }

    /// Small scale-punch on press (feels like a real mobile game button).
    public class PressBounce : MonoBehaviour, UnityEngine.EventSystems.IPointerDownHandler, UnityEngine.EventSystems.IPointerUpHandler
    {
        float target = 1f;
        public void OnPointerDown(UnityEngine.EventSystems.PointerEventData e) { target = 0.93f; }
        public void OnPointerUp(UnityEngine.EventSystems.PointerEventData e) { target = 1f; }
        void Update()
        {
            float s = Mathf.Lerp(transform.localScale.x, target, 1f - Mathf.Exp(-25f * Time.unscaledDeltaTime));
            transform.localScale = new Vector3(s, s, 1);
        }
    }

    /// Keeps a RectTransform inside Screen.safeArea (notch / punch-hole phones), plus a minimum side margin.
    public class SafeArea : MonoBehaviour
    {
        public float minSide = 28f; // canvas units, applied by the layout code
        Rect last; Vector2Int lastScreen;
        void OnEnable() { Apply(); }
        void Update() { if (Screen.safeArea != last || lastScreen.x != Screen.width || lastScreen.y != Screen.height) Apply(); }
        void Apply()
        {
            var rt = (RectTransform)transform; last = Screen.safeArea; lastScreen = new Vector2Int(Screen.width, Screen.height);
            if (AgniBoot.ProofMode || Screen.width <= 0 || Screen.height <= 0 || last.width <= 0) { rt.anchorMin = Vector2.zero; rt.anchorMax = Vector2.one; rt.offsetMin = rt.offsetMax = Vector2.zero; return; }
            Vector2 min = last.position, max = last.position + last.size;
            rt.anchorMin = new Vector2(min.x / Screen.width, min.y / Screen.height);
            rt.anchorMax = new Vector2(max.x / Screen.width, max.y / Screen.height);
            rt.offsetMin = rt.offsetMax = Vector2.zero;
        }
    }

    /// Canvas + scaler + safe area + event system, landscape reference 2400×1080 (20:9), matched on height so 16:9 just gets narrower.
    public static class CanvasMaker
    {
        public static Canvas Make(string name, Camera cam, float planeDistance, int order, out RectTransform safe)
        {
            var go = new GameObject(name); go.layer = 5;
            var c = go.AddComponent<Canvas>();
            c.renderMode = RenderMode.ScreenSpaceCamera; c.worldCamera = cam; c.planeDistance = planeDistance; c.sortingOrder = order;
            var sc = go.AddComponent<CanvasScaler>();
            sc.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize; sc.referenceResolution = new Vector2(2400, 1080);
            sc.screenMatchMode = CanvasScaler.ScreenMatchMode.MatchWidthOrHeight; sc.matchWidthOrHeight = 1f;
            go.AddComponent<GraphicRaycaster>();
            safe = K.R("Safe", go.transform); safe.Fill(); safe.gameObject.AddComponent<SafeArea>();
            return c;
        }
        public static void EnsureEventSystem()
        {
            if (Object.FindAnyObjectByType<UnityEngine.EventSystems.EventSystem>() != null) return;
            var es = new GameObject("EventSystem", typeof(UnityEngine.EventSystems.EventSystem));
#if ENABLE_INPUT_SYSTEM
            es.AddComponent<UnityEngine.InputSystem.UI.InputSystemUIInputModule>();
#else
            es.AddComponent<UnityEngine.EventSystems.StandaloneInputModule>();
#endif
        }
    }
}
